      tempWorkspace.clear();

      if (spr.blocklyXML) {
        Blockly.Xml.domToWorkspace(spr.blocklyXML, tempWorkspace);
      }

      var blocks = tempWorkspace.getTopBlocks(true);
      for (var block of blocks) {
        compileRoot(block.getRootBlock(), spr);
        await new Promise((r) => setTimeout(r, 2));
      }
      await new Promise((r) => setTimeout(r, 2));
